#!/usr/bin/env python3
from __future__ import annotations
import html, io, json, re, sys
from pathlib import Path
from urllib.parse import urljoin

import requests
from bs4 import BeautifulSoup
from PIL import Image

ROOT=Path(sys.argv[1] if len(sys.argv)>1 else ".").resolve()
SITE=ROOT/"site"
QA=ROOT/"deployment"/"qa"
SOURCE=json.loads((ROOT/"deployment"/"sok-full-line-source.json").read_text())


def write(rel, content):
    p=ROOT/rel
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(content, encoding="utf-8")


def replace_once(rel, old, new):
    p=ROOT/rel
    text=p.read_text(encoding="utf-8")
    if old not in text:
        raise SystemExit(f"missing replacement marker in {rel}: {old[:120]}")
    p.write_text(text.replace(old,new,1), encoding="utf-8")


def download_official_media():
    session=requests.Session()
    session.headers.update({"User-Agent":"Mozilla/5.0 (compatible; ElevationUpScalesCatalog/1.0; +https://elevationupscales.com)"})
    for item in SOURCE:
        if item.get("existingImage"):
            continue
        slug=item["slug"]
        dest=SITE/"assets"/"brands"/"sok"/slug/"hero.webp"
        if dest.exists() and dest.stat().st_size>5000:
            continue
        page=session.get(item["sourcePage"],timeout=45)
        page.raise_for_status()
        soup=BeautifulSoup(page.text,"html.parser")
        image_url=""
        for attrs in ({"property":"og:image"},{"name":"twitter:image"},{"property":"twitter:image"}):
            tag=soup.find("meta",attrs=attrs)
            if tag and tag.get("content"):
                image_url=html.unescape(tag["content"].strip());break
        if not image_url:
            candidates=re.findall(r'https://static\.wixstatic\.com/media/[^"\'<> ]+',page.text)
            if candidates:image_url=html.unescape(candidates[0])
        if not image_url:
            raise SystemExit(f"official image not found for {item['sku']}")
        image_url=urljoin(item["sourcePage"],image_url)
        data=session.get(image_url,timeout=60).content
        if len(data)<5000:raise SystemExit(f"official image too small for {item['sku']}")
        im=Image.open(io.BytesIO(data))
        im.load()
        if im.width<300 or im.height<200:raise SystemExit(f"official image dimensions too small for {item['sku']}: {im.size}")
        if im.mode not in ("RGB","RGBA"):
            im=im.convert("RGBA" if "A" in im.getbands() else "RGB")
        im.thumbnail((1600,1600),Image.Resampling.LANCZOS)
        dest.parent.mkdir(parents=True,exist_ok=True)
        im.save(dest,"WEBP",quality=86,method=6)
        print(f"media {item['sku']} -> {dest.relative_to(ROOT)} {im.size}")


def patch_runtime():
    p=SITE/"sok-full-line-runtime.js"
    text=p.read_text(encoding="utf-8")
    text=text.replace('  if(sku==="SK12V100PC"||sku==="SK48V100N")return handleSokAvailabilityPublicApi(request,env,"/api/sok/reservations");\n','')
    text=text.replace('  const id=`SOK-RES-${crypto.randomUUID()}`,stamp=now();\n  const context=', '  let availabilityMode="purchase_options";\n  if(sku==="SK12V100PC"||sku==="SK48V100N"){try{const row=await db.prepare("SELECT availability_mode FROM eus_sok_product_ops WHERE upper(sku)=? LIMIT 1").bind(sku).first();availabilityMode=clean(row?.availability_mode,30)||availabilityMode;}catch(_){}}\n  const id=`SOK-RES-${crypto.randomUUID()}`,stamp=now();\n  const context=')
    text=text.replace("VALUES (?,?,?,'purchase_options',?,?,?,?,?,'RECEIVED',?,?,?,?,?,?,?,?,?,?,?)", "VALUES (?,?,?,?,?,?,?,?,?,'RECEIVED',?,?,?,?,?,?,?,?,?,?,?)")
    text=text.replace(".bind(id,sku,quantity,destination,name,email,phone,context,commercial?1:0,stamp,stamp,inquiryIntent,company,postalCode,intendedUse,demandType,island,siteType)", ".bind(id,sku,quantity,availabilityMode,destination,name,email,phone,context,commercial?1:0,stamp,stamp,inquiryIntent,company,postalCode,intendedUse,demandType,island,siteType)")
    p.write_text(text,encoding="utf-8")


def patch_worker():
    replace_once("site/_worker.js", 'import { handleSokAvailabilityPublicApi, handleSokAvailabilityAdminApi, publicSokCatalogProducts } from "./sok-availability-runtime.js";', 'import { handleSokAvailabilityAdminApi, publicSokCatalogProducts } from "./sok-availability-runtime.js";\nimport { handleSokFullLinePublicApi, handleSokFullLinePage } from "./sok-full-line-runtime.js";')
    replace_once("site/_worker.js", '      "/sok-availability-runtime.js",\n      "/sync-admin-runtime.js",', '      "/sok-availability-runtime.js",\n      "/sok-full-line-runtime.js",\n      "/sok-full-line-data.js",\n      "/sync-admin-runtime.js",')
    replace_once("site/_worker.js", '      "/sok-availability-runtime.js","/sync-admin-runtime.js"', '      "/sok-availability-runtime.js","/sok-full-line-runtime.js","/sok-full-line-data.js","/sync-admin-runtime.js"')
    replace_once("site/_worker.js", 'if(url.pathname==="/api/sok/catalog"||url.pathname==="/api/sok/reservations") return handleSokAvailabilityPublicApi(request,env,url.pathname);', 'if(url.pathname==="/api/sok/catalog"||url.pathname==="/api/sok/reservations") return handleSokFullLinePublicApi(request,env,url.pathname);')
    replace_once("site/_worker.js", '    const response=await coreWorker.fetch(request,env,ctx);', '    if(url.pathname.startsWith("/sok/")){const page=await handleSokFullLinePage(request,env,url.pathname);if(page)return page;}\n    const response=await coreWorker.fetch(request,env,ctx);')


def patch_routes():
    p=SITE/"_routes.json"; data=json.loads(p.read_text())
    include=data["include"]
    for route in ["/sok/*","/sok-full-line-runtime.js","/sok-full-line-data.js"]:
        if route not in include:include.append(route)
    p.write_text(json.dumps(data,indent=2)+"\n")


