def static_product_js():
    return '''(()=>{"use strict";const sku=String(document.body.dataset.sokSku||"").trim().toUpperCase();if(!sku)return;const track=(type,details={})=>window.EUSIntent?.track?.(type,sku,{source:"sok-product-page",...details});track("sok_product_view");document.addEventListener("click",e=>{const a=e.target.closest("[data-sok-page-action]");if(!a)return;const action=a.dataset.sokPageAction;const type=action==="commercial"?"sok_commercial_request":action==="hawaii"?"sok_hawaii_request":action==="email"?"sok_email_inquiry":"sok_purchase_options_click";track(type,{stage:"product-page"});});})();'''


