    extra='''.sok-filter--full{margin:1.2rem 0 1.5rem}.sok-grid--full{grid-template-columns:repeat(3,minmax(0,1fr))}.sok-card--full{grid-template-columns:1fr}.sok-card--full .sok-card__media img{min-height:240px;aspect-ratio:4/3}.sok-card--full h3 a{color:inherit;text-decoration:none}.sok-card__price--options{font-size:1.15rem;color:#e6c66a}.sok-product-page{background:#060606;color:#f5f0e6}.sok-product-hero{padding:clamp(2.5rem,6vw,5rem) 0;background:radial-gradient(circle at 80% 20%,rgba(230,198,106,.1),transparent 35%),#070707}.sok-product-hero__grid{display:grid;grid-template-columns:minmax(300px,.85fr) minmax(0,1fr);gap:clamp(2rem,5vw,5rem);align-items:center}.sok-product-hero figure{margin:0;background:#fff;border-radius:22px;overflow:hidden}.sok-product-hero figure img{display:block;width:100%;aspect-ratio:4/3;object-fit:contain}.sok-product-hero h1{font-size:clamp(2.2rem,5vw,4.2rem);line-height:1.02;margin:.5rem 0 1rem}.sok-product-facts{display:flex;flex-wrap:wrap;gap:.5rem}.sok-product-facts span{border:1px solid rgba(255,255,255,.14);border-radius:999px;padding:.45rem .7rem}.sok-product-price{font-size:2rem;font-weight:850;margin:1rem 0}.sok-product-price--options{font-size:1.2rem;color:#e6c66a}.sok-product-actions{display:flex;gap:.65rem;flex-wrap:wrap;margin-top:1.25rem}.sok-product-content{padding:clamp(2.5rem,6vw,5rem) 0}.sok-product-content__grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1rem}.sok-product-section{border:1px solid rgba(255,255,255,.12);border-radius:18px;padding:1.35rem;background:#101010}.sok-product-section--wide{grid-column:1/-1}.sok-product-section h2{margin:.3rem 0 .8rem}.sok-product-section li{margin:.45rem 0}.sok-product-specs{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:.6rem}.sok-product-specs div{background:rgba(255,255,255,.05);padding:.75rem;border-radius:12px}.sok-product-specs dt{font-size:.82rem;color:#c9c0b2}.sok-product-specs dd{margin:.15rem 0 0;font-weight:700}.sok-literature-link{display:inline-block;color:#e6c66a}.sok-product-caution{border-left:3px solid #e6c66a;padding-left:.8rem}.sok-order-product{font-weight:700;color:#e6c66a}@media(max-width:1050px){.sok-grid--full{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:760px){.sok-grid--full,.sok-product-hero__grid,.sok-product-content__grid{grid-template-columns:1fr}.sok-product-section--wide{grid-column:auto}.sok-product-specs{grid-template-columns:1fr}.sok-product-actions{display:grid}.sok-product-actions .button{text-align:center}}'''
