def sitemap():
    p=SITE/"sitemap.xml"; text=p.read_text()
    block='  <url><loc>https://elevationupscales.com/sok-batteries</loc><lastmod>2026-09-04</lastmod><changefreq>weekly</changefreq><priority>0.9</priority></url>\n'
    for item in SOURCE:block+=f'  <url><loc>https://elevationupscales.com/sok/{item["slug"]}/</loc><lastmod>2026-09-04</lastmod><changefreq>weekly</changefreq><priority>0.8</priority></url>\n'
    if "/sok-batteries" not in text:text=text.replace("</urlset>",block+"</urlset>")
    p.write_text(text)


def qa_static():
    return '''import fs from "node:fs";import assert from "node:assert/strict";import {SOK_FULL_LINE_PUBLIC} from "../../site/sok-full-line-data.js";import {__sokFullLineTest} from "../../site/sok-full-line-runtime.js";
assert.equal(SOK_FULL_LINE_PUBLIC.length,20);assert.equal(new Set(SOK_FULL_LINE_PUBLIC.map(p=>p.sku)).size,20);assert.equal(new Set(SOK_FULL_LINE_PUBLIC.map(p=>p.id)).size,20);assert.equal(SOK_FULL_LINE_PUBLIC.filter(p=>p.batteryRelevant).length,9);const bySku=Object.fromEntries(SOK_FULL_LINE_PUBLIC.map(p=>[p.sku,p]));assert.equal(bySku.SK12V100PC.priceCents,31900);assert.equal(bySku.SK48V100N.priceCents,119900);for(const p of SOK_FULL_LINE_PUBLIC){assert.equal(p.catalogStatus,"PUBLISHED");assert.ok(["PURCHASE_OPTIONS","COMMERCIAL_ONLY"].includes(p.publicPurchaseMode));assert.equal(p.promotion.eligible,false);assert.equal(p.promotion.couponEligible,false);if(!["SK12V100PC","SK48V100N"].includes(p.sku))assert.equal(p.priceCents,null,`${p.sku} must remain unpriced until MAP is verified`);assert.ok(p.detailUrl.startsWith("/sok/"));assert.ok(p.primaryImage.startsWith("/assets/brands/sok/"));assert.ok(fs.existsSync(`site${p.primaryImage}`),`missing local image ${p.primaryImage}`);const raw=JSON.stringify(p);for(const token of ["supplierCost","dropShipCost","supplierInventory","sourceWarehouse","sourcePage","primary_carrier","carrier_state","economics_state","landedCost","marginCents"])assert.equal(raw.includes(token),false,`public leak ${token}`);}assert.equal(bySku["SOK-48V-CABINET"].publicPurchaseMode,"COMMERCIAL_ONLY");assert.match(bySku["SOK-48V-CABINET"].specs.Configuration,/Cabinet only/i);const sitemap=fs.readFileSync("site/sitemap.xml","utf8");assert.match(sitemap,/\/sok-batteries/);for(const p of SOK_FULL_LINE_PUBLIC)assert.ok(sitemap.includes(`https://elevationupscales.com${p.detailUrl}`),`sitemap missing ${p.sku}`);const worker=fs.readFileSync("site/_worker.js","utf8");assert.match(worker,/handleSokFullLinePublicApi/);assert.match(worker,/handleSokFullLinePage/);assert.match(worker,/sok-full-line-runtime\.js/);const routes=fs.readFileSync("site/_routes.json","utf8");assert.match(routes,/\/sok\/\*/);const collection=fs.readFileSync("site/sok-batteries.js","utf8");for(const event of ["sok_collection_view","sok_catalog_filter","sok_purchase_options_click","sok_email_inquiry","sok_commercial_request","sok_hawaii_request"])assert.match(collection,new RegExp(event));const order=fs.readFileSync("site/sok-order.html","utf8")+fs.readFileSync("site/sok-order.js","utf8");for(const token of ["hawaiiIsland","siteType","postalCode","intendedUse","demandType","productUrl"])assert.match(order,new RegExp(token));assert.match(order,/casey@elevationupscales\.com/);assert.equal(__sokFullLineTest.SOK_FULL_LINE_PUBLIC.length,20);console.log("SOK full-line static gate: PASS");'''


def qa_preview():
    return '''#!/usr/bin/env bash
set -euo pipefail
base="${1%/}"
test -n "$base"
for route in /sok-batteries /sok/sk12v100h/ /sok/sk24v150ph/ /sok/sk48v100n/ /sok/sktc30-smart-battery-monitor/ /sok/48v-battery-cabinet/ /sok-order.html; do code=$(curl -sS -L --retry 8 --retry-all-errors --retry-delay 2 -o /tmp/sok-full-page -w '%{http_code}' "$base$route" || true); echo "$route=$code"; test "$code" = "200"; done
curl -sS -L --fail "$base/api/sok/catalog" -o /tmp/sok-full.json
node - <<'NODE'
const fs=require('fs'),d=JSON.parse(fs.readFileSync('/tmp/sok-full.json','utf8'));if(!Array.isArray(d.products)||d.products.length!==20)throw new Error(`expected 20 SOK products, got ${d.products?.length}`);const by=Object.fromEntries(d.products.map(p=>[p.sku,p]));if(by.SK12V100PC.priceCents!==31900||by.SK48V100N.priceCents!==119900)throw new Error('anchor MAP mismatch');if(by.SK12V100H.priceCents!==null||by.SK24V150PH.priceCents!==null)throw new Error('unverified price published');if(by['SOK-48V-CABINET'].publicPurchaseMode!=='COMMERCIAL_ONLY')throw new Error('cabinet purchase mode');const raw=JSON.stringify(d);for(const token of ['supplierCost','dropShipCost','supplierInventory','sourceWarehouse','sourcePage','primary_carrier','carrier_state','economics_state','landedCost','marginCents'])if(raw.includes(token))throw new Error(`public leak ${token}`);console.log('full-line public API: PASS');
NODE
for path in /assets/brands/sok/sk12v100h/hero.webp /assets/brands/sok/sk24v150ph/hero.webp /assets/brands/sok/sktc30-smart-battery-monitor/hero.webp; do code=$(curl -sS -L --retry 6 --retry-all-errors -o /tmp/sok-image -w '%{http_code}' "$base$path"||true); test "$code" = "200"; test "$(wc -c </tmp/sok-image)" -gt 5000; done
for runtime in /sok-full-line-runtime.js /sok-full-line-data.js; do code=$(curl -sS -o /tmp/runtime -w '%{http_code}' "$base$runtime"||true); test "$code" = "404"; done
echo 'SOK full-line preview smoke: PASS'
'''


def patch_rc():
    p=ROOT/".github"/"workflows"/"release-candidate-gate.yml"; text=p.read_text()
    branch="      - work/sok-full-line-catalog-2026-09-04\n"
    if "work/sok-full-line-catalog-2026-09-04" not in text:text=text.replace("      - work/sok-4-6-catalog-commercialization-2026-09-04\n", "      - work/sok-4-6-catalog-commercialization-2026-09-04\n"+branch)
    marker='      - name: Check JavaScript syntax\n'
    gate='      - name: SOK full-line static gate\n        shell: bash\n        run: |\n          set -euo pipefail\n          node deployment/qa/sok-full-line-static.mjs\n\n'
    if "SOK full-line static gate" not in text:text=text.replace(marker,gate+marker)
    receipt='      - name: Record release-candidate receipt\n'
    smoke='      - name: Smoke SOK full-line preview\n        shell: bash\n        env:\n          DEPLOYMENT_URL: ${{ steps.deploy.outputs.deployment-url }}\n        run: |\n          set -euo pipefail\n          bash deployment/qa/sok-full-line-preview.sh "$DEPLOYMENT_URL"\n\n'
    if "Smoke SOK full-line preview" not in text:text=text.replace(receipt,smoke+receipt)
    p.write_text(text)


def main():
    download_official_media()
    patch_runtime();patch_worker();patch_routes()
    write("site/sok-batteries.html",collection_html());write("site/sok-batteries.js",collection_js())
    write("site/sok-order.html",order_html());write("site/sok-order.js",order_js());write("site/sok-static-product.js",static_product_js())
    append_css();patch_lithium_link();sitemap()
    write("deployment/qa/sok-full-line-static.mjs",qa_static());write("deployment/qa/sok-full-line-preview.sh",qa_preview())
    (ROOT/"deployment/qa/sok-full-line-preview.sh").chmod(0o755)
    patch_rc()
    print("SOK full-line one-pass build prepared")

if __name__=="__main__":main()
